theorem extracted_1.{u_1, uG} {G : Type uG} [inst : AddCommGroup G] [hGm : MeasurableSpace G]
  [inst_1 : DiscreteMeasurableSpace G] {Ω : Type u_1} [inst_2 : MeasurableSpace Ω] {μ : Measure Ω}
  [inst_3 : IsProbabilityMeasure μ] {H : AddSubgroup G} {U : Ω → G} (hunif : IsUniform (↑H) U μ) {A : Finset G}
  (hA : A.Nonempty) (hU : Measurable U) (μ' : Measure G) (hμ' : IsProbabilityMeasure μ')
  (habs : ∀ (y : G), (Measure.map (Prod.fst + Prod.snd) (μ'.prod (uniformOn ↑A))) {y} = 0 → (Measure.map U μ) {y} = 0) :
  let T := Prod.fst;
  Measurable T →
    let UA := Prod.snd;
    Measurable UA →
      let x := MeasureSpace.mk (μ'.prod (uniformOn ↑A));
      ℙ = μ'.prod (uniformOn ↑A) →
        IsProbabilityMeasure (uniformOn ↑A) →
          IsProbabilityMeasure (Measure.map T ℙ) →
            IndepFun T UA ℙ → IsUniform (↑A) UA ℙ → IsProbabilityMeasure ℙ := by
  hprod, Measure.map_fst_prod]; simp [hμ']

