theorem extracted_1.{u_3, u_2, u_1, uG} {G : Type uG} [inst : AddCommGroup G] [hGm : MeasurableSpace G] {Ω : Type u_1}
  [inst_1 : MeasurableSpace Ω] {μ : Measure Ω} (X : Ω → G) {S : Type u_2} {T : Type u_3} (Y : Ω → S) {A : Finset G}
  {f : S → T} (hf : Injective f) ⦃y : T⦄
  (hy : y ∈ Function.support fun s => (μ (f ∘ Y ⁻¹' {s})).toReal * ρ[X ; μ[|f ∘ Y ⁻¹' {s}] # A])
  (this : f ∘ Y ⁻¹' {y} ≠ ∅) : y ∈ range f := by
  simp [I]

theorem extracted_1.{u_3, u_2, u_1, uG} {G : Type uG} [inst : AddCommGroup G] [hGm : MeasurableSpace G] {Ω : Type u_1}
  [inst_1 : MeasurableSpace Ω] {μ : Measure Ω} (X : Ω → G) {S : Type u_2} {T : Type u_3} (Y : Ω → S) {A : Finset G}
  {f : S → T} (hf : Injective f) ⦃y : T⦄
  (hy : y ∈ Function.support fun s => (μ (f ∘ Y ⁻¹' {s})).toReal * ρ[X ; μ[|f ∘ Y ⁻¹' {s}] # A]) :
  f ∘ Y ⁻¹' {y} ≠ ∅ := by
  ext z; simp [hf.eq_iff]

theorem extracted_1.{u_3, u_2, u_1, uG} {G : Type uG} [inst : AddCommGroup G] [hGm : MeasurableSpace G]
  [inst_1 : DiscreteMeasurableSpace G] {Ω : Type u_1} [inst_2 : MeasureSpace Ω] {A : Finset G} {η : ℝ} {X₁ X₂ : Ω → G}
  (h_min : phiMinimizes X₁ X₂ η A ℙ) {Ω₁ : Type u_2} {Ω₂ : Type u_3} [inst_3 : MeasurableSpace Ω₁]
  [inst_4 : MeasurableSpace Ω₂] {μ₁ : Measure Ω₁} {μ₂ : Measure Ω₂} [inst_5 : IsProbabilityMeasure μ₁]
  [inst_6 : IsProbabilityMeasure μ₂] {X₁' : Ω₁ → G} {X₂' : Ω₂ → G} (hX₁' : Measurable X₁') (hX₂' : Measurable X₂') :
  let Ω' := G × G;
  IsProbabilityMeasure (Measure.map X₁' μ₁) →
    IsProbabilityMeasure (Measure.map X₂' μ₂) →
      let m := (Measure.map X₁' μ₁).prod (Measure.map X₂' μ₂);
      IsProbabilityMeasure m →
        let x := MeasureSpace.mk m;
        ℙ = m →
          let Y₁ := Prod.fst;
          let Y₂ := Prod.snd;
          phi X₁ X₂ η A ℙ ≤ phi Y₁ Y₂ η A ℙ → IdentDistrib Y₁ X₁' ℙ μ₁ → Measure.map Y₂ ℙ = Measure.map X₂' μ₂ := by
  simp [Y₂, hP, m]

theorem extracted_1.{u_3, u_2, u_1, uG} {G : Type uG} [inst : AddCommGroup G] [hGm : MeasurableSpace G]
  [inst_1 : DiscreteMeasurableSpace G] {Ω : Type u_1} [inst_2 : MeasureSpace Ω] {A : Finset G} {η : ℝ} {X₁ X₂ : Ω → G}
  (h_min : phiMinimizes X₁ X₂ η A ℙ) {Ω₁ : Type u_2} {Ω₂ : Type u_3} [inst_3 : MeasurableSpace Ω₁]
  [inst_4 : MeasurableSpace Ω₂] {μ₁ : Measure Ω₁} {μ₂ : Measure Ω₂} [inst_5 : IsProbabilityMeasure μ₁]
  [inst_6 : IsProbabilityMeasure μ₂] {X₁' : Ω₁ → G} {X₂' : Ω₂ → G} (hX₁' : Measurable X₁') (hX₂' : Measurable X₂') :
  let Ω' := G × G;
  IsProbabilityMeasure (Measure.map X₁' μ₁) →
    IsProbabilityMeasure (Measure.map X₂' μ₂) →
      let m := (Measure.map X₁' μ₁).prod (Measure.map X₂' μ₂);
      IsProbabilityMeasure m →
        let x := MeasureSpace.mk m;
        ℙ = m →
          let Y₁ := Prod.fst;
          let Y₂ := Prod.snd;
          phi X₁ X₂ η A ℙ ≤ phi Y₁ Y₂ η A ℙ → Measure.map Y₁ ℙ = Measure.map X₁' μ₁ := by
  simp [Y₁, hP, m]

theorem extracted_1.{u_1, uG} {G : Type uG} [inst : AddCommGroup G] [hGm : MeasurableSpace G]
  [inst_1 : DiscreteMeasurableSpace G] {Ω : Type u_1} [inst_2 : MeasureSpace Ω] {A : Finset G}
  [inst_3 : IsProbabilityMeasure ℙ] {Y₁ Y₂ Y₃ Y₄ : Ω → G} (hY₁ : Measurable Y₁) (hY₂ : Measurable Y₂)
  (hY₃ : Measurable Y₃) (hY₄ : Measurable Y₄) (h_indep : iIndepFun (fun x => hGm) ![Y₁, Y₂, Y₃, Y₄] ℙ)
  (hA : A.Nonempty) :
  let S := Y₁ + Y₂ + Y₃ + Y₄;
  let T₁ := Y₁ + Y₂;
  let T₂ := Y₁ + Y₃;
  let T₁' := Y₃ + Y₄;
  ρ[T₁ | ⟨T₂, S⟩ # A] ≤ ρ[T₁ | S # A] + I[T₁ : T₂|S] / 2 →
    ρ[T₁ | S # A] ≤ (ρ[T₁ # A] + ρ[T₁' # A] + d[T₁ # T₁']) / 2 →
      ρ[T₁ | ⟨T₂, S⟩ # A] ≤
        (ρ[Y₁ # A] + ρ[Y₂ # A] + ρ[Y₃ # A] + ρ[Y₄ # A]) / 4 + (d[Y₁ # Y₂] + d[Y₃ # Y₄]) / 4 +
          (d[T₁ # T₁'] + I[T₁ : T₂|S]) / 2 := by
  fun_prop

theorem extracted_1.{u_1, uG} {G : Type uG} [inst : AddCommGroup G] [hGm : MeasurableSpace G]
